import json, os
for f in sorted(os.listdir('.')):
    if f.startswith('fewshot_') and f.endswith('.json'):
        data = json.load(open(f))
        # Write compact version with just metrics + predictions (problem_id, gold, pred, correct)
        compact = {
            'experiment': data.get('experiment',''),
            'model': data.get('model',''),
            'condition': data.get('condition',''),
            'shots': data.get('shots', 0),
            'metrics': data.get('metrics', {}),
            'predictions': [
                {'problem_id': p['problem_id'], 'gold': p['gold'], 'pred': p['pred'], 'correct': p['correct']}
                for p in data.get('predictions', [])
            ]
        }
        out = json.dumps(compact, separators=(',',':'))
        with open(f'/tmp/compact_{f}', 'w') as fout:
            fout.write(out)
        print(f'{f}: full={len(json.dumps(data, separators=(\",\",\":\")))} compact={len(out)}')
"
